#pragma once
// SUMMIT 381B: runtime item identity manifest. No external JSON dependency.
// Deliberately accepts only the canonical, restricted schema generated by publish_item_codes_381b.py.
#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <fstream>
#include <iterator>
#include <set>
#include <string>
#include <vector>

namespace summit_item_codes_381b {
struct Entry { std::string name; unsigned long value; };
struct Reader {
    const std::string &s; size_t i;
    explicit Reader(const std::string &src):s(src),i(0) {}
    void ws() { while(i<s.size() && (s[i]==' ' || s[i]=='\n' || s[i]=='\r' || s[i]=='\t')) ++i; }
    bool take(char c) { ws(); if(i>=s.size() || s[i]!=c) return false; ++i; return true; }
    bool word(std::string &out) {
        ws(); if(i>=s.size() || s[i]!='"') return false; ++i;
        out.clear(); while(i<s.size() && s[i]!='"') {
            unsigned char c=static_cast<unsigned char>(s[i++]);
            // No escapes/control/non-ASCII in this strictly generated identity manifest.
            if(c<0x20 || c>0x7e || c=='\\' || out.size()>=64) return false;
            out.push_back(static_cast<char>(c));
        }
        if(i>=s.size()) return false;
        ++i; return true;
    }
    bool field(const char *key) { std::string got;return word(got) && got==key && take(':'); }
    bool end() { ws();return i==s.size(); }
};
inline bool code_ok(const std::string &name) {
    if(name.size()!=5) return false;
    for(size_t n=0;n<2;n++)if(name[n]<'A'||name[n]>'Z')return false;
    for(size_t n=2;n<5;n++)if(name[n]<'0'||name[n]>'9')return false;
    return true;
}
inline bool hex_ok(const std::string &h, unsigned long &v) {
    if(h.size()!=10||h.substr(0,2)!="0x")return false;
    unsigned long acc=0;
    for(size_t k=2;k<h.size();k++) {
        char c=h[k]; int digit=(c>='0'&&c<='9')?c-'0':((c>='A'&&c<='F')?c-'A'+10:-1);
        if(digit<0)return false;
        acc=(acc<<4)|static_cast<unsigned long>(digit);
    }
    v=acc;return v!=0;
}
inline bool parse(const std::string &src, std::vector<Entry> &result, unsigned long limit) {
    Reader p(src);std::string val;
    if(!p.take('{')||!p.field("schema")||!p.word(val)||val!="summit.item-code-map/v1"||!p.take(',')||!p.field("entries")||!p.take('['))return false;
    std::set<std::string> seen;
    if(!p.take(']')) {
        do {
            Entry e;std::string hex;
            if(!p.take('{')||!p.field("code")||!p.word(e.name)||!p.take(',')||!p.field("numeric")||!p.word(hex)||!p.take('}'))return false;
            if(!code_ok(e.name)||!hex_ok(hex,e.value)||!seen.insert(e.name).second||result.size()>=limit)return false;
            result.push_back(e);
            if(p.take(']'))break;
            if(!p.take(','))return false;
        } while(true);
    }
    return p.take('}')&&p.end()&&!result.empty();
}
template<typename Item>
inline bool load(Item *items, int capacity, int *loaded, bool *present) {
    if(loaded)*loaded=0;
    if(present)*present=false;
    const char *path="Content/packs/item_code_map.json";
    std::ifstream f(path,std::ios::in|std::ios::binary);
    if(!f.good())return false; // Legacy fallback allowed only if file is absent.
    if(present)*present=true;
    std::string src((std::istreambuf_iterator<char>(f)),std::istreambuf_iterator<char>());
    if(src.size()>256*1024 || capacity<=0) { std::fprintf(stderr,"[ITEM_CODE_JSON] INVALID_SIZE %s\n",path);return false; }
    std::vector<Entry> entries;
    if(!parse(src,entries,static_cast<unsigned long>(capacity))) {
        std::fprintf(stderr,"[ITEM_CODE_JSON] INVALID_SCHEMA_OR_ID %s\n",path);return false;
    }
    // Commit only after complete schema/ID verification.
    for(size_t k=0;k<entries.size();k++) {
        items[k].CODE=entries[k].value;
        std::memset(items[k].LastCategory,0,sizeof(items[k].LastCategory));
        std::strncpy(items[k].LastCategory,entries[k].name.c_str(),sizeof(items[k].LastCategory)-1);
        items[k].sItemInfo.CODE=entries[k].value;
    }
    if(loaded)*loaded=static_cast<int>(entries.size());
    std::printf("[ITEM_CODE_JSON] loaded=%d file=%s\n",static_cast<int>(entries.size()),path);
    return true;
}
} // namespace summit_item_codes_381b
